int linear_search(const int a[], int n, int target) {
  for (int i = 0; i < n; i++)
    if (a[i] == target) return i;
  return -1;
}

int sentinel_search(int a[], int n, int target) {
  int last = a[n - 1]; a[n - 1] = target;
  int i = 0; while (a[i] != target) i++;
  a[n - 1] = last;
  return (i < n - 1 || last == target) ? i : -1;
}

Node *find(Node *head, int key) {
  for (Node *p = head; p; p = p->next) if (p->val == key) return p;
  return NULL;
}
